import pandas as pd

def clean(df):
    df = df.copy()
    df['Price'] = pd.to_numeric(
        df['Price'].astype(str).str.replace(r'[$,]', '', regex=True),
        errors='coerce'
    )
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    df.loc[df['Quantity'] < 0, 'Quantity'] = df.loc[df['Quantity'] < 0, 'Quantity'].abs()

    region_map = {
        'north': 'North', 'south': 'South', 'east': 'East', 'west': 'West',
        'wst': 'West', 'suoth': 'South'
    }

    def norm_region(v):
        if pd.isna(v):
            return v
        s = str(v).strip()
        return region_map.get(s.lower(), s.title())

    df['Region'] = df['Region'].map(norm_region)
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Region'])
    sums = d.groupby('Region', sort=False)['Quantity'].sum()
    return {str(k): int(v) for k, v in sums.items()}
